"import { initializeApp } from 'firebase/app';
import { getFirestore, collection, getDocs, doc, updateDoc } from 'firebase/firestore';
import * as dotenv from 'dotenv';

dotenv.config();

const firebaseConfig = {
  apiKey: process.env.EXPO_PUBLIC_FIREBASE_API_KEY,
  authDomain: process.env.EXPO_PUBLIC_FIREBASE_AUTH_DOMAIN,
  projectId: process.env.EXPO_PUBLIC_FIREBASE_PROJECT_ID,
  storageBucket: process.env.EXPO_PUBLIC_FIREBASE_STORAGE_BUCKET,
  messagingSenderId: process.env.EXPO_PUBLIC_FIREBASE_MESSAGING_SENDER_ID,
  appId: process.env.EXPO_PUBLIC_FIREBASE_APP_ID,
  measurementId: process.env.EXPO_PUBLIC_FIREBASE_MEASUREMENT_ID
};

const app = initializeApp(firebaseConfig);
const db = getFirestore(app);

async function updateACRepairRating() {
  try {
    const servicesCol = collection(db, 'services');
    const snapshot = await getDocs(servicesCol);

    let updatedCount = 0;
    for (const serviceDoc of snapshot.docs) {
      const data = serviceDoc.data();
      const name = (data.name || '').toLowerCase();

      if (name.includes('ac repair') || name.includes('gas filling')) {
        console.log(`Found service: "${data.name}" (ID: ${serviceDoc.id}). Current rating: ${data.rating}`);
        await updateDoc(doc(db, 'services', serviceDoc.id), {
          rating: 4.5
        });
        console.log(`Updated rating to 4.5 for: ${data.name}`);
        updatedCount++;
      }
    }

    if (updatedCount === 0) {
      console.log('No service containing "ac repair" or "gas filling" was found.');
    } else {
      console.log(`Successfully updated ${updatedCount} services.`);
    }
  } catch (error) {
    console.error('Error updating Firestore document:', error);
  }
}

updateACRepairRating();
"

