"import { initializeApp } from 'firebase/app';
import { getAuth, createUserWithEmailAndPassword, signInWithEmailAndPassword } from 'firebase/auth';
import { getFirestore, collection, getDocs, doc, updateDoc } from 'firebase/firestore';
import * as dotenv from 'dotenv';
dotenv.config();

const firebaseConfig = {
  apiKey: process.env.EXPO_PUBLIC_FIREBASE_API_KEY,
  authDomain: process.env.EXPO_PUBLIC_FIREBASE_AUTH_DOMAIN,
  projectId: process.env.EXPO_PUBLIC_FIREBASE_PROJECT_ID,
  storageBucket: process.env.EXPO_PUBLIC_FIREBASE_STORAGE_BUCKET,
  messagingSenderId: process.env.EXPO_PUBLIC_FIREBASE_MESSAGING_SENDER_ID,
  appId: process.env.EXPO_PUBLIC_FIREBASE_APP_ID
};

const app = initializeApp(firebaseConfig);
const db = getFirestore(app);
const auth = getAuth(app);

const run = async () => {
  const email = `temp-rating-updater-${Date.now()}@test.com`;
  const password = 'TemporaryPassword123!';

  try {
    console.log('Registering temporary auth user...');
    await createUserWithEmailAndPassword(auth, email, password);
    console.log('Authenticated successfully!');

    const snap = await getDocs(collection(db, 'services'));
    let updatedCount = 0;

    for (const d of snap.docs) {
      const name = (d.data().name || '').toLowerCase();
      if (name.includes('ac repair') || name.includes('gas filling') || name.includes('ac repairing')) {
        console.log('Found service:', d.data().name);
        await updateDoc(doc(db, 'services', d.id), { rating: 4.5 });
        console.log('Updated to 4.5 successfully');
        updatedCount++;
      }
    }

    if (updatedCount === 0) {
      console.log('No service containing "ac repair", "ac repairing" or "gas filling" was found.');
    }
  } catch(err) {
    console.error('Error running update:', err);
  }
};

run();
"

